        const box_sizes = [_]usize{ 1, 2, 4, 8, 16 };
        var counts = ArrayList(usize).init(self.allocator);
        defer counts.deinit();

        for (box_sizes) |size| {
            const count = self.boxCount(size);
            if (count > 0) {
                counts.append(count) catch continue;
