        if (counts.items.len < 2) {
            return 1.0;
        }

        var sum_x: f64 = 0.0;
        var sum_y: f64 = 0.0;
        var sum_xy: f64 = 0.0;
        var sum_x2: f64 = 0.0;

        var i: usize = 0;
        for (counts.items) |count| {
