        const graph_density = @as(f64, @floatFromInt(total_edges)) / @as(f64, @floatFromInt(total_possible));
        const subgraph_density = @as(f64, @floatFromInt(subgraph_edges)) / @as(f64, @floatFromInt(total_subgraph_possible));

